                    $affectedRows += $this->aPeriodo->save($con);
                }
                $this->setPeriodo($this->aPeriodo);
            }

            if ($this->isNew() || $this->isModified()) {
                // persist changes
                if ($this->isNew()) {
                    $this->doInsert($con);
                } else {
                    $this->doUpdate($con);
                }
                $affectedRows += 1;
                $this->resetModified();
            }

            if ($this->detallePrestamosScheduledForDeletion !== null) {
                if (!$this->detallePrestamosScheduledForDeletion->isEmpty()) {
